-- security_nov22: shared guard, included at the top of every migration here (01-04). Safe to run many times.
-- pb_sec.guard(tag, function, md5): refuses (and so rolls the whole migration back) when the live definition of a
-- function we replace is not the one read on Nov 21 2026. When it matches, the live definition is saved first in
-- pb_sec.fn_backup, so the undo files put back the exact text that was live (no copy typed by hand).
-- Running a migration a second time: the backup row is already there, so it goes through again.
create schema if not exists pb_sec;
revoke all on schema pb_sec from public;
revoke all on schema pb_sec from anon, authenticated;
create table if not exists pb_sec.fn_backup (
  tag      text not null,          -- which migration (nov22_01 ...)
  sig      text not null,          -- regprocedure text, e.g. public.pb_session_gate()
  def      text not null,          -- pg_get_functiondef() as it was live
  md5      text not null,
  saved_at timestamptz not null default now(),
  primary key (tag, sig)
);
alter table pb_sec.fn_backup enable row level security;
revoke all on table pb_sec.fn_backup from public;
revoke all on table pb_sec.fn_backup from anon, authenticated;

create or replace function pb_sec.guard(p_tag text, p_sig text, p_md5 text) returns void
language plpgsql set search_path = '' as $f$
declare v_def text; v_md5 text;
begin
  v_def := pg_get_functiondef(p_sig::regprocedure);
  v_md5 := md5(v_def);
  if v_md5 = p_md5 then
    insert into pb_sec.fn_backup (tag, sig, def, md5) values (p_tag, p_sig, v_def, v_md5) on conflict (tag, sig) do nothing;
    return;
  end if;
  if exists (select 1 from pb_sec.fn_backup b where b.tag = p_tag and b.sig = p_sig) then return; end if; -- this migration ran before
  -- (throwaway local test database only: the stand-in functions there are not the live text)
  if current_setting('pb_sec.guard', true) = 'skip-local-test' then
    insert into pb_sec.fn_backup (tag, sig, def, md5) values (p_tag, p_sig, v_def, v_md5) on conflict (tag, sig) do nothing;
    return;
  end if;
  raise exception 'pb_sec: % changed on live since Nov 21 2026 (md5 % , expected %). Nothing was applied. Re-read it and rebase this migration.', p_sig, v_md5, p_md5;
end $f$;
revoke all on function pb_sec.guard(text, text, text) from public;
revoke all on function pb_sec.guard(text, text, text) from anon, authenticated;

-- undo helper: puts back every function a migration replaced, exactly as it was live
create or replace function pb_sec.restore(p_tag text) returns integer
language plpgsql set search_path = '' as $f$
declare r record; n integer := 0;
begin
  for r in select b.sig, b.def from pb_sec.fn_backup b where b.tag = p_tag order by b.sig loop
    execute r.def; n := n + 1;
  end loop;
  delete from pb_sec.fn_backup where tag = p_tag;
  return n;
end $f$;
revoke all on function pb_sec.restore(text) from public;
revoke all on function pb_sec.restore(text) from anon, authenticated;

-- security_nov22 01 (review finding 1, HIGH): two-step login is enforced by the server, not only by the app's code sheet.
-- Before: public.pb_session_gate() (the PostgREST pre-request check on every app request) never looked at the session's
-- assurance level, so a password-only (aal1) session of a login that has two-step login on could call every company
-- function (pb_crew_list, pb_ai_company_overview, run records ...) straight from the API.
-- After: such a session is refused on every API request with the error the app already treats as "not now, nothing filed,
-- try again later" (pb:signed_out, HTTP 401) and detail 'code_needed'. The app does NOT sign out on it (its one-device
-- handler only acts on other_device / moved / ended / in_use / full), so the code sheet stays up; once the code is
-- entered the session is aal2 and everything goes through. The code sheet itself uses only the Auth API
-- (mfa.getAuthenticatorAssuranceLevel / listFactors / challengeAndVerify), which this gate never sees.
-- Also adds public.pb_session_ok(): a no-op RPC edge functions call with the caller's own token so the same gate
-- (two-step code, device lock, ended sessions) applies to them (edge/crew-admin, edge/weather).
-- Run as postgres, in one transaction (the whole file). Safe to run twice. Undo: undo/99_undo_01.sql.

-- (00_guard.sql is included here by mk.py for the apply copy: apply/01_mfa_gate.apply.sql)
select pb_sec.guard('nov22_01', 'public.pb_session_gate()', '86427e6a38841f324615c92e515d8673');

CREATE OR REPLACE FUNCTION public.pb_session_gate()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_txt text := current_setting('request.jwt.claims', true); v_claims jsonb; v_s text; v_sid uuid; v_uid uuid; v_reason text; h record; v_kind text;
begin
  if v_txt is null or v_txt = '' or left(v_txt, 1) <> '{' then return; end if;
  v_claims := v_txt::jsonb;
  if v_claims->>'role' is distinct from 'authenticated' then return; end if;
  v_s := v_claims->>'session_id';
  if v_s is null or v_s !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return; end if;
  v_sid := v_s::uuid;
  select l.end_reason into v_reason from pb_auth.sessions_log l where l.session_id = v_sid;
  if not exists (select 1 from auth.sessions s where s.id = v_sid) then
    raise exception using errcode = 'PT401', message = 'pb:signed_out', detail = coalesce(v_reason, 'ended');
  end if;
  if v_reason = 'in_use' then raise exception using errcode = 'PT401', message = 'pb:signed_out', detail = 'in_use'; end if;
  v_s := v_claims->>'sub';
  if v_s is null or v_s !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then return; end if;
  v_uid := v_s::uuid;
  -- security_nov22 01: two-step login on and the code not entered in this session (aal1): nothing but the code sheet.
  -- Same shape the app's queues already wait on (nothing filed, tried again later); 'code_needed' never signs the app out.
  if coalesce(v_claims->>'aal', '') <> 'aal2'
     and exists (select 1 from auth.mfa_factors f where f.user_id = v_uid and f.status = 'verified') then
    raise exception using errcode = 'PT401', message = 'pb:signed_out', detail = 'code_needed';
  end if;
  if v_reason = 'full' then
    raise exception using errcode = 'PT401', message = 'pb:signed_out', detail = 'full',
      hint = coalesce((select string_agg(x.kind || '|' || floor(extract(epoch from x.act))::bigint, ',') from pb_auth.slots(v_uid, v_sid) x), '');
  end if;
  select hh.session_id, hh.device_id, hh.last_at into h from pb_auth.holder hh where hh.user_id = v_uid;
  if not found or h.session_id is null or h.session_id = v_sid then return; end if;
  if not exists (select 1 from auth.sessions s where s.id = h.session_id) then return; end if;
  if not pb_auth.one_at_a_time(v_uid) then return; end if;
  if h.last_at > now() - interval '5 minutes' then
    select d.kind into v_kind from pb_auth.devices d where d.user_id = v_uid and d.device_id = h.device_id;
    raise exception using errcode = 'PT401', message = 'pb:signed_out', detail = 'locked',
      hint = coalesce(v_kind, 'phone') || '|' || greatest(1, ceil(extract(epoch from (h.last_at + interval '5 minutes' - now())))::integer) || '|0';
  elsif pb_auth.permit_open(v_uid) then
    select d.kind into v_kind from pb_auth.devices d where d.user_id = v_uid and d.device_id = h.device_id;
    raise exception using errcode = 'PT401', message = 'pb:signed_out', detail = 'locked', hint = coalesce(v_kind, 'phone') || '|0|1';
  end if;
end $function$;

-- edge functions call this with the caller's own token; the gate above runs first (PostgREST pre-request), so a
-- refused session gets the gate's answer (pb:signed_out + code_needed / locked / ended ...), a good one gets true.
create or replace function public.pb_session_ok() returns boolean
language sql stable set search_path = '' as $f$ select auth.uid() is not null $f$;
revoke all on function public.pb_session_ok() from public;
revoke all on function public.pb_session_ok() from anon;
grant execute on function public.pb_session_ok() to authenticated;

-- security_nov22 01 test: two-step login at the gate. Runs after 01_mfa_gate.sql in the same transaction and always ends
-- by raising 'RESULT: ...', so everything (in the block form, the migration too) is rolled back.
create function pg_temp.s1_signin(p_user uuid, p_aal text) returns uuid language plpgsql as $f$
declare v uuid := gen_random_uuid(); as_auth boolean := current_setting('pbsec.as_auth', true) = '1';
begin
  if as_auth then set local role supabase_auth_admin; end if;
  insert into auth.sessions (id, user_id, created_at, aal) values (v, p_user, now(), 'aal1');
  if p_aal = 'aal2' then update auth.sessions set aal = 'aal2' where id = v; end if;
  reset role; return v;
end $f$;
create function pg_temp.s1_gate(p_role text, p_user uuid, p_sid uuid, p_aal text) returns text language plpgsql as $f$
declare d text;
begin
  perform set_config('request.jwt.claims', jsonb_strip_nulls(jsonb_build_object('role', p_role, 'sub', p_user, 'session_id', p_sid, 'aal', p_aal))::text, true);
  perform public.pb_session_gate(); return 'ok';
exception when others then get stacked diagnostics d = pg_exception_detail;
  return case when sqlstate = 'PT401' and sqlerrm = 'pb:signed_out' then 'refused:' || coalesce(d, '') else 'ERR ' || sqlstate || ' ' || sqlerrm end;
end $f$;

do $test$
declare
  pass integer; fail integer; fails text; notes text := ''; tag text := substr(md5(random()::text), 1, 10);
  um uuid := gen_random_uuid(); up uuid := gen_random_uuid(); uu uuid := gen_random_uuid();
  sm1 uuid; sm2 uuid; sp uuid; su uuid; x text; n integer;
begin
  create temp table t_chk (i serial, name text, ok boolean, got text) on commit drop;
  insert into auth.users (id, email) select v, 'pbsec01-' || tag || '-' || row_number() over () || '@example.invalid' from unnest(array[um, up, uu]) v;
  insert into auth.mfa_factors (id, user_id, friendly_name, factor_type, status, created_at, updated_at)
    values (gen_random_uuid(), um, 't', 'totp', 'verified', now(), now()), (gen_random_uuid(), uu, 't', 'totp', 'unverified', now(), now());
  begin set local role supabase_auth_admin; reset role; perform set_config('pbsec.as_auth', '1', true); notes := ' [sessions as supabase_auth_admin]';
  exception when others then perform set_config('pbsec.as_auth', '0', true); notes := ' [sessions as ' || current_user || ']'; end;
  sm1 := pg_temp.s1_signin(um, 'aal1');   -- password only
  sm2 := pg_temp.s1_signin(um, 'aal2');   -- password + code
  sp := pg_temp.s1_signin(up, 'aal1');    -- no two-step login
  su := pg_temp.s1_signin(uu, 'aal1');    -- started turning it on, never finished

  x := pg_temp.s1_gate('authenticated', um, sm1, 'aal1');
  insert into t_chk (name, ok, got) values ('1a two-step on, password only (aal1): refused, code_needed', x = 'refused:code_needed', x);
  x := pg_temp.s1_gate('authenticated', um, sm1, null);
  insert into t_chk (name, ok, got) values ('1b two-step on, token without aal claim: refused', x = 'refused:code_needed', x);
  x := pg_temp.s1_gate('authenticated', um, sm2, 'aal2');
  insert into t_chk (name, ok, got) values ('1c two-step on, code entered (aal2): passes', x = 'ok', x);
  x := pg_temp.s1_gate('authenticated', up, sp, 'aal1');
  insert into t_chk (name, ok, got) values ('1d no two-step login, aal1: passes (crews unchanged)', x = 'ok', x);
  x := pg_temp.s1_gate('authenticated', uu, su, 'aal1');
  insert into t_chk (name, ok, got) values ('1e unfinished (unverified) factor, aal1: passes', x = 'ok', x);
  x := pg_temp.s1_gate('anon', null, null, null);
  insert into t_chk (name, ok, got) values ('1f app key only (anon: take-slot, why, peek): passes', x = 'ok', x);
  x := pg_temp.s1_gate('service_role', null, null, null);
  insert into t_chk (name, ok, got) values ('1g service role: passes', x = 'ok', x);
  -- an ended session still says ended (order of checks kept)
  delete from auth.sessions where id = sm1;
  x := pg_temp.s1_gate('authenticated', um, sm1, 'aal1');
  insert into t_chk (name, ok, got) values ('1h ended aal1 session: still "ended", not code_needed', x ~ '^refused:(ended|other_device)$', x);
  -- the detail is not one the app signs out on (pb1dEnded acts only on these five)
  insert into t_chk (name, ok, got) values ('1i code_needed is not a sign-out reason in the app', not ('code_needed' = any (array['other_device', 'moved', 'ended', 'in_use', 'full'])), '');
  -- pb_session_ok: the edge functions' check
  perform set_config('request.jwt.claims', jsonb_build_object('role', 'authenticated', 'sub', um, 'session_id', sm2, 'aal', 'aal2')::text, true);
  insert into t_chk (name, ok, got) select '1j pb_session_ok() true for a good session', public.pb_session_ok(), '';
  insert into t_chk (name, ok, got) values ('1k pb_session_ok: authenticated may call, anon may not',
    has_function_privilege('authenticated', 'public.pb_session_ok()', 'execute') and not has_function_privilege('anon', 'public.pb_session_ok()', 'execute'), '');
  insert into t_chk (name, ok, got) values ('1l gate still the pre-request function name', to_regprocedure('public.pb_session_gate()') is not null, '');
  select count(*) into n from pb_sec.fn_backup where fn_backup.tag = 'nov22_01';
  insert into t_chk (name, ok, got) values ('1m the live gate was saved for undo', n = 1, n::text);
  insert into t_chk (name, ok, got) values ('1n pb_sec not reachable from the API', not has_schema_privilege('authenticated', 'pb_sec', 'usage') and not has_schema_privilege('anon', 'pb_sec', 'usage'), '');
  -- undo puts the old gate back: password-only passes again (as before)
  sm1 := pg_temp.s1_signin(um, 'aal1');
  perform pb_sec.restore('nov22_01');
  x := pg_temp.s1_gate('authenticated', um, sm1, 'aal1');
  insert into t_chk (name, ok, got) values ('1o undo (restore) brings back the old gate exactly (aal1 passes again)', x = 'ok', x);

  select count(*) filter (where ok), count(*) filter (where ok is not true), coalesce(string_agg(name || ' [got: ' || coalesce(got, 'null') || ']', ' ; ' order by i) filter (where ok is not true), '') into pass, fail, fails from t_chk;
  raise exception 'RESULT: % pass, % fail% %', pass, fail, case when fail > 0 then ' | FAILED: ' || fails else '' end, notes;
end $test$;

rollback;
